struct Point: Equatable {
    let x: Int
    let y: Int
}
print(Point(x: 1, y: 2) == Point(x: 1, y: 2))

struct Tag: Hashable { let name: String }
let tags: Set = [Tag(name: "a"), Tag(name: "a")]
print(tags.count)

struct Level: Comparable {
    let value: Int
    static func < (a: Level, b: Level) -> Bool {
        a.value < b.value
    }
}
print(Level(value: 1) < Level(value: 3))

